import Foundation
@MainActor enum BilibiliTests {
    static func run()->Bool {
        var checks=0
        func check(_ c:@autoclosure()->Bool,_ n:String){checks+=1;if !c(){fputs("FAIL Bilibili: \(n)\n",stderr);exit(1)}}
        check(BilibiliRemote.samePlayerDocument(URL(string:"https://www.bilibili.com/video/BVOne/?vd_source=tracking&p=2"),snapshotURL:"https://www.bilibili.com/video/BVOne/?p=2"),"tracking parameters do not block prepared player")
        check(!BilibiliRemote.samePlayerDocument(URL(string:"https://www.bilibili.com/video/BVTwo/"),snapshotURL:"https://www.bilibili.com/video/BVOne/"),"previous document cannot reveal next player")
        check(!BilibiliRemote.samePlayerDocument(URL(string:"https://www.bilibili.com/video/BVOne/?p=2"),snapshotURL:"https://www.bilibili.com/video/BVOne/?p=1"),"different multipart cannot reveal stale player")
        var gate=CatalogLoadGate();check(gate.begin(),"first pagination request");check(!gate.begin(),"coalesce overlapping requests");gate.finish(added:true);check(gate.begin(),"more after growth");gate.finish(added:false);check(!gate.begin(),"stop when no new content");gate.reset();check(gate.begin(),"reload resets pagination")
        let tv=BilibiliRemote();tv.snapshot.cards=(0..<9).map{BilibiliCard(id:"c\($0)",title:"视频\($0)",poster:"https://i0.hdslb.com/test.jpg")};tv.focus=HomeFocus(row:1,column:0)
        tv.navigate(.right);check(tv.cardIndex==1,"horizontal film focus");tv.navigate(.down);check(tv.cardIndex==5,"vertical film focus");tv.navigate(.down);check(tv.cardIndex==8,"short final row clamps");tv.navigate(.down);check(tv.cardIndex==8,"no manual load-more focus target")
        tv.focus=HomeFocus(row:1,column:3);tv.navigate(.right);check(tv.cardIndex==4,"right crosses row edge");tv.navigate(.left);check(tv.cardIndex==3,"left crosses row edge")
        tv.focus=HomeFocus(row:1,column:0);tv.navigate(.left);check(tv.cardIndex==0,"first card boundary");tv.focus=HomeFocus(row:3,column:0);tv.navigate(.right);check(tv.cardIndex==8,"last card boundary")
        tv.snapshot.isPlayer=true;tv.openQuality();check(tv.panel == .quality,"native quality panel opens");tv.navigate(.back);tv.snapshot.isPlayer=false
        tv.openSearch();check(tv.panel == .search,"native search opens");tv.pressSearchKey(0);check(tv.searchDraft=="a","screen keyboard input");tv.pressSearchKey(37);check(tv.searchDraft.isEmpty,"screen keyboard delete");tv.searchDraft="中文关键词";tv.pressSearchKey(38);check(tv.searchDraft.isEmpty,"clear search")
        tv.navigate(.back);check(tv.panel == .none,"back dismisses search")
        check(WebService.allCases.count==3 && WebService.allCases.map(\.rawValue)==["youtube","netflix","bilibili"],"removed providers absent")
        tv.focus=HomeFocus(row:0,column:2);tv.navigate(.right);check(tv.focus.column==2,"toolbar ends at refresh without hidden home target")
        var returnedHome=false;tv.onHome={returnedHome=true};tv.back();check(returnedHome,"catalog back returns to app home")
        let player=BilibiliRemote();player.snapshot.isPlayer=true;player.snapshot.duration=100;player.snapshot.current=30;player.snapshot.paused=false;player.showPlaybackHUD=false
        var fullscreenChanges=0;player.onFullscreen={fullscreenChanges+=1}
        player.navigate(.up);check(player.controlsFocused && player.controlIndex==0,"up focuses playback controls")
        player.navigate(.right);check(player.controlIndex==1 && player.snapshot.current==30,"control arrows navigate instead of seeking")
        player.navigate(.right);check(player.controlIndex==1,"minimal controls stop at fullscreen")
        player.navigate(.select);check(fullscreenChanges==1 && player.panel == .none,"second control is fullscreen without duplicate episodes entry")
        player.navigate(.down);check(player.panel == .none,"standalone video does not open empty selection or recommendations")
        player.snapshot.episodes=(1...5).map{BilibiliEpisode(id:"e\($0)",title:"第 \($0) 集",number:$0,current:$0==3)}
        player.navigate(.down);check(player.panel == .episodes && player.episodeIndex==2,"down opens same playlist focused on current episode")
        player.navigate(.left);check(player.episodeIndex==1 && player.snapshot.current==30,"browsing previous episode does not switch or seek")
        player.navigate(.right);player.navigate(.right);check(player.episodeIndex==3 && player.snapshot.current==30,"browsing next episode does not switch or seek")
        player.navigate(.back);check(player.panel == .none && player.controlsFocused,"back closes sheet before controls")
        player.navigate(.back);check(!player.showPlaybackHUD && !player.controlsFocused,"next back dismisses controls")
        player.navigate(.menu);check(player.controlsFocused,"menu opens playback controls");player.navigate(.menu);check(!player.showPlaybackHUD,"menu closes playback controls")
        player.snapshot.paused=true;player.showPlaybackHUD=true;player.navigate(.back);check(!player.showPlaybackHUD && player.snapshot.paused,"back can hide paused HUD without resuming")
        player.navigate(.up);player.navigate(.select);check(player.panel == .quality,"first control opens quality")
        player.navigate(.back);player.navigate(.down);check(player.panel == .episodes && player.episodeIndex==2,"down from controls shares current-episode focus")
        player.navigate(.back);player.hidePlaybackControls();player.navigate(.down);check(player.panel == .episodes,"down from playback opens episodes");player.stop()
        check(BilibiliCreator(id:"74161368",name:"作者",avatar:"").url != nil,"numeric creator identity permits official space")
        check(BilibiliCreator(id:"../other",name:"作者",avatar:"").url==nil,"creator identity cannot escape space path")
        let authorVideo=BilibiliCreatorVideo(id:"https://www.bilibili.com/video/BVExample/",title:"作品",poster:"",duration:"10:00")
        var shelf=CreatorBrowseState();check(shelf.merge([authorVideo,authorVideo])==1,"creator pages deduplicate cover and title links")
        check(shelf.merge([BilibiliCreatorVideo(id:"https://other.test/video/BVExample/",title:"bad",poster:"",duration:"")])==0,"creator selection rejects external playback URLs")
        shelf.move(10);check(shelf.index==0,"creator focus clamps to existing cards")
        let group=BilibiliCreatorCollection(id:"系列A",title:"系列A",poster:"",detail:"20 个视频")
        check(shelf.mergeCollections([group,group])==1,"creator collection rows deduplicate repeated groups")
        var collectionFocus=CreatorCollectionFocus()
        check(collectionFocus.index == -1,"creator begins on explicit latest-video tab")
        collectionFocus.select(0,count:3);check(collectionFocus.index==0,"first collection follows latest")
        collectionFocus.select(2,count:3);check(collectionFocus.index==2,"can select another collection without entering a new page")
        collectionFocus.select(3,count:3);check(collectionFocus.index==2,"collection right boundary clamps")
        collectionFocus.select(-1,count:3);check(collectionFocus.index == -1,"left returns to latest videos")
        collectionFocus.select(5,count:0);check(collectionFocus.index == -1,"empty collection list retains latest")
        check(collectionFocus.neighbors(count:4)==[0,1],"latest warms only the next two collection tabs")
        collectionFocus.select(1,count:4);check(collectionFocus.neighbors(count:4)==[2,0],"predict only immediate right and left neighbors")
        collectionFocus.select(3,count:4);check(collectionFocus.neighbors(count:4)==[2],"prefetch respects final tab boundary")
        check(collectionFocus.neighbors(count:0).isEmpty,"empty tabs schedule no speculative reads")
        let emptyGroup=BilibiliCreatorCollection(id:"系列·哇塞电台 · 0",title:"哇塞电台",poster:"",detail:"0 个视频",count:0)
        check(emptyGroup.count==0,"official zero-count collection is distinguishable from unknown count")
        var knownEmpty=CreatorBrowseState();knownEmpty.empty=true;knownEmpty.canLoad=false
        check(knownEmpty.videos.isEmpty && knownEmpty.empty && !knownEmpty.canLoad,"empty collection is a completed result, not loading")
        _ = knownEmpty.merge([authorVideo]);check(!knownEmpty.empty,"actual new content clears an earlier empty result")
        let restored=BilibiliRemote();check(!restored.loginChecked,"startup waits for site login state");restored.updateLoginStatus(true);check(restored.catalogActions==[.search,.refresh],"logged-in toolbar omits redundant account status action");check(restored.loggedIn && restored.loginChecked,"restore existing site session without QR panel");restored.updateLoginStatus(nil);check(restored.loggedIn,"unavailable header does not log out");restored.updateLoginStatus(false);check(!restored.loggedIn && restored.loginChecked,"site logout updates native state");restored.stop()
        var globalMenus=0;let catalogMenu=BilibiliRemote();catalogMenu.onAppMenu={globalMenus+=1};catalogMenu.navigate(.menu);check(globalMenus==1 && catalogMenu.panel == .none,"catalog menu uses shared control center without duplicate actions panel");catalogMenu.stop()
        let next=BilibiliNextEpisode(url:"https://www.bilibili.com/video/BVNext/",title:"下一集")
        var countdown=EpisodeCountdown()
        countdown.observe(key:"episode1",ended:false,rewound:true,eligible:true,next:next,now:0);check(countdown.target==nil,"playing does not start countdown")
        countdown.observe(key:"episode1",ended:true,rewound:false,eligible:true,next:next,now:100);check(countdown.remaining==10 && countdown.target==next,"actual end starts ten second countdown")
        check(countdown.tick(now:100.3)==nil && countdown.remaining==10,"round countdown seconds up")
        check(countdown.tick(now:101.1)==nil && countdown.remaining==9,"monotonic countdown updates")
        countdown.cancel();check(countdown.tick(now:150)==nil,"cancel stops delayed next action")
        countdown.observe(key:"episode1",ended:true,rewound:false,eligible:true,next:next,now:151);check(countdown.target==nil,"cancel does not rearm on repeated ended snapshot")
        countdown.observe(key:"episode1",ended:false,rewound:true,eligible:true,next:next,now:160)
        countdown.observe(key:"episode1",ended:true,rewound:false,eligible:true,next:next,now:170);check(countdown.target==next,"replay allows a new countdown")
        check(countdown.tick(now:180)==next && countdown.remaining==0,"deadline advances exactly once");check(countdown.tick(now:181)==nil,"late duplicate tick cannot advance twice")
        countdown.observe(key:"episode2",ended:true,rewound:false,eligible:true,next:nil,now:190);check(countdown.target==nil,"last episode never starts countdown")
        countdown.observe(key:"episode2",ended:true,rewound:false,eligible:true,next:next,now:191);check(countdown.remaining==10,"late-loaded successor can start countdown")
        countdown.observe(key:"episode3",ended:true,rewound:false,eligible:false,next:next,now:200);check(countdown.target==nil,"trial or inactive player cannot start countdown")
        countdown.observe(key:"episode4",ended:true,rewound:false,eligible:true,next:BilibiliNextEpisode(url:"https://other.test/video/BVNext/",title:"bad"),now:210);check(countdown.target==nil,"foreign successor rejected")
        countdown.observe(key:"episode5",ended:true,rewound:false,eligible:true,next:next,now:220);countdown.observe(key:"catalog",ended:false,rewound:false,eligible:false,next:nil,now:221);check(countdown.tick(now:240)==nil,"navigation invalidates pending deadline")
        let endedPlayer=BilibiliRemote();endedPlayer.snapshot.isPlayer=true;endedPlayer.autoplay.observe(key:"episode",ended:true,rewound:false,eligible:true,next:next,now:0)
        endedPlayer.navigate(.right);check(endedPlayer.autoplayFocus==1,"countdown right selects cancel");endedPlayer.navigate(.back);check(endedPlayer.autoplay.target==nil && endedPlayer.showPlaybackHUD,"back cancels countdown before navigating");endedPlayer.stop()
        tv.stop();print("PASS: \(checks) Bilibili and catalogue checks");return true
    }
}
